class Configuration {
    // In-Class Initializers (ICI) establish defaults
    int timeout_ms = 500;
    bool cached = true;
    std::string key;

public:
    // Only 'key' is explicitly initialized.
    // 'timeout_ms' and 'cached' implicitly use their ICI values.
    Configuration(std::string k) : key(std::move(k)) {
        // timeout_ms is 500
    }

    // Default Ctor uses all ICI values
    Configuration() {}
};
